// A tab you cannot link to is a tab you cannot show anybody. `?stage=` names it,
// and the body is stamped on the first paint as well as on every later click so
// a panel outside this runtime does not have to wait for one.
//
// The site always opens on the argument. It used to remember that you had seen
// it and skip straight to the quote, which is right for the person who built it
// and wrong for everybody else: a judge arriving at a screen of numbers with no
// reason to care about them is the one visit that has to go well. A link that
// carries a job is still a link to that job, because someone sent it on purpose.
stage: (function () {
  const asked = new URLSearchParams(location.search).get('stage');
  const stage = (asked === 'sim' || asked === 'story' || asked === 'app') ? asked
    : (deepLinked ? 'app' : 'story');
  try { document.body.setAttribute('data-stage', stage); } catch (e) { /* no dom */ }
  return stage;
})()
